def merge(ranges):
    """Join overlapping and neighbouring closed integer ranges. See TASK.md."""
    # Validate all ranges
    for start, end in ranges:
        if start > end:
            raise ValueError(f"Invalid range: start {start} > end {end}")

    if not ranges:
        return []

    # Sort by start
    sorted_ranges = sorted(ranges)

    # Merge overlapping and adjacent ranges
    merged = [sorted_ranges[0]]
    for start, end in sorted_ranges[1:]:
        last_start, last_end = merged[-1]
        # If current range overlaps or is adjacent to the last one, merge
        if start <= last_end + 1:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged


def subtract(ranges, holes):
    """The integers in `ranges` that are not in `holes`, as merged ranges."""
    # Validate all ranges
    for start, end in ranges:
        if start > end:
            raise ValueError(f"Invalid range: start {start} > end {end}")
    for start, end in holes:
        if start > end:
            raise ValueError(f"Invalid range: start {start} > end {end}")

    if not ranges:
        return []

    merged_ranges = merge(ranges)
    merged_holes = merge(holes)

    if not merged_holes:
        return merged_ranges

    result = []
    for r_start, r_end in merged_ranges:
        current_start = r_start
        for h_start, h_end in merged_holes:
            if h_end < current_start:
                # Hole is entirely before current position
                continue
            if h_start > r_end:
                # Hole is entirely after current range
                break
            if h_start <= current_start:
                # Hole overlaps with current start
                current_start = max(current_start, h_end + 1)
            else:
                # There's a gap between current_start and h_start
                result.append((current_start, h_start - 1))
                current_start = h_end + 1

        # Add any remaining range after all holes
        if current_start <= r_end:
            result.append((current_start, r_end))

    return result


def count(ranges):
    """How many distinct integers the ranges hold."""
    # Validate and merge
    for start, end in ranges:
        if start > end:
            raise ValueError(f"Invalid range: start {start} > end {end}")

    merged = merge(ranges)
    return sum(end - start + 1 for start, end in merged)
